import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BGob8Fzn.js";const u=JSON.parse('{"title":"How it works","description":"Architecture of react-native-universal-sheet - a plain JavaScript sheet store, a shared surface model, and native presenters on iOS and Android with a DOM renderer on web.","frontmatter":{"description":"Architecture of react-native-universal-sheet - a plain JavaScript sheet store, a shared surface model, and native presenters on iOS and Android with a DOM renderer on web.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-universal-sheet/guide/how-it-works"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-universal-sheet/guide/how-it-works"}],["meta",{"property":"og:title","content":"How it works · React Native Universal Sheet"}],["meta",{"property":"og:description","content":"Architecture of react-native-universal-sheet - a plain JavaScript sheet store, a shared surface model, and native presenters on iOS and Android with a DOM renderer on web."}],["meta",{"name":"twitter:title","content":"How it works · React Native Universal Sheet"}],["meta",{"name":"twitter:description","content":"Architecture of react-native-universal-sheet - a plain JavaScript sheet store, a shared surface model, and native presenters on iOS and Android with a DOM renderer on web."}]]},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md","lastUpdated":1794234315000}'),o={name:"guide/how-it-works.md"};function r(i,e,d,c,h,l){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h1><p>The library has three layers. Knowing them helps when something behaves unexpectedly.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> your code ── present / dismiss / snapTo ──►  SheetManager  (plain JS store, no React)</span></span>
<span class="line"><span>                                                   │ subscribe</span></span>
<span class="line"><span>                                                   ▼</span></span>
<span class="line"><span>                                         NativeSheetProvider  (renders one surface per open sheet)</span></span>
<span class="line"><span>                                                   │</span></span>
<span class="line"><span>                                                   ▼</span></span>
<span class="line"><span>                                  describeSurface()  →  SurfaceModel  (platform-neutral props)</span></span>
<span class="line"><span>                                     │                                   │</span></span>
<span class="line"><span>                       iOS / Android ▼                                   ▼ web</span></span>
<span class="line"><span>                 NativeSheetHost (native view)                 DOM dialog in document.body</span></span>
<span class="line"><span>      UISheetPresentationController / BottomSheetDialog</span></span></code></pre></div><h2 id="_1-the-manager" tabindex="-1">1. The manager <a class="header-anchor" href="#_1-the-manager" aria-label="Permalink to &quot;1. The manager&quot;">​</a></h2><p><code>SheetManager</code> is an ordinary class. It validates each config, fills in defaults from the variant, keeps the ordered stack, runs auto-dismiss timers and calls your event callbacks. It has no React or native code, which is why it is fully unit-tested.</p><h2 id="_2-the-provider" tabindex="-1">2. The provider <a class="header-anchor" href="#_2-the-provider" aria-label="Permalink to &quot;2. The provider&quot;">​</a></h2><p><code>NativeSheetProvider</code> subscribes to the manager with <code>useSyncExternalStore</code> and renders one surface per open sheet, after your <code>children</code>. Because sheet content lives here, not in the screen that opened it, closing or navigating away from that screen leaves the sheet and its state alone.</p><p>The provider also listens for the Android hardware back button and dismisses the topmost sheet that allows it.</p><h2 id="_3-the-surface" tabindex="-1">3. The surface <a class="header-anchor" href="#_3-the-surface" aria-label="Permalink to &quot;3. The surface&quot;">​</a></h2><p>Each sheet&#39;s config is turned into a <code>SurfaceModel</code>: snap points become fractions of screen height, defaults are filled in, colours are passed through. Both renderers read this same model, so a prop means the same thing on every platform.</p><p><strong>iOS.</strong> A native view is re-parented into a view controller presented with <code>UISheetPresentationController</code>. Snap points become custom detents (iOS 16+) or medium/large (iOS 15).</p><p><strong>Android.</strong> The native view is placed inside a Material <code>BottomSheetDialog</code>. Each sheet is its own dialog window, so stacked sheets nest and the Activity is untouched. Snap points map to half-expanded and expanded states.</p><p><strong>Web.</strong> <code>SheetSurface.web.tsx</code> renders a fixed-position <code>role=&quot;dialog&quot;</code> element in <code>document.body</code> through a React portal, with a backdrop, slide or scale transitions and Escape to close. Bundlers pick this file automatically through the <code>.web.tsx</code> extension.</p><h2 id="events-flow-back" tabindex="-1">Events flow back <a class="header-anchor" href="#events-flow-back" aria-label="Permalink to &quot;Events flow back&quot;">​</a></h2><p>When the user swipes a sheet away or drags it to another height, the platform sends <code>onDismiss</code> or <code>onSnapChange</code> to the surface, which calls <code>manager.handleNativeDismiss</code> / <code>handleNativeSnapChange</code>. The manager updates the stack and calls your <code>onDidDismiss</code> / <code>onSnapChange</code>.</p>`,15)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
